import { CalendarState } from './calendar-state.interface';

export class MonthViewState implements CalendarState {
  getTitle(): string {
    return 'Vista Mes';
  }

  getDateRange(currentDate: Date): string {
    return currentDate.toLocaleDateString('es', { month: 'long', year: 'numeric' });
  }

  navigate(currentDate: Date, direction: 'prev' | 'next'): Date {
    const newDate = new Date(currentDate);
    newDate.setMonth(currentDate.getMonth() + (direction === 'next' ? 1 : -1));
    return newDate;
  }

  getViewData(date: Date, data: any): any {
    const days = this.getDaysOfMonth(date);
    const weeks = this.groupDaysIntoWeeks(days);

    return {
      date,
      weeks,
      weekDays: ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom']
    };
  }

  private getDaysOfMonth(date: Date): any[] {
    const year = date.getFullYear();
    const month = date.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);

    const days = [];
    const firstDayOfWeek = firstDay.getDay();
    const offset = firstDayOfWeek === 0 ? 6 : firstDayOfWeek - 1;

    // Días del mes anterior
    for (let i = offset; i > 0; i--) {
      const prevDate = new Date(year, month, 1 - i);
      days.push({
        number: prevDate.getDate(),
        date: prevDate.toISOString().split('T')[0],
        isCurrentMonth: false,
        events: []
      });
    }

    // Días del mes actual
    const today = new Date().toISOString().split('T')[0];
    for (let i = 1; i <= lastDay.getDate(); i++) {
      const currentDate = new Date(year, month, i);
      const dateStr = currentDate.toISOString().split('T')[0];
      days.push({
        number: i,
        date: dateStr,
        isCurrentMonth: true,
        isToday: dateStr === today,
        events: []
      });
    }

    // Días del mes siguiente
    const remainingCells = 42 - days.length;
    for (let i = 1; i <= remainingCells; i++) {
      const nextDate = new Date(year, month + 1, i);
      days.push({
        number: nextDate.getDate(),
        date: nextDate.toISOString().split('T')[0],
        isCurrentMonth: false,
        events: []
      });
    }

    return days;
  }

  private groupDaysIntoWeeks(days: any[]): any[][] {
    const weeks = [];
    for (let i = 0; i < days.length; i += 7) {
      weeks.push(days.slice(i, i + 7));
    }
    return weeks;
  }
}
