import { Injectable } from '@angular/core';
import { HttpClient, HttpParams, HttpHeaders } from '@angular/common/http';
import { Observable, throwError, of } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';
import { environment } from '../../environments/environment';
import { AuthService } from '../../../src/app/core/services/auth.service';
import { NotificationService } from '../../../src/app/core/services/notification/notification.service';

// ========== INTERFACES ==========

export interface Horario {
  horario_id: number;
  personal_id: number;
  fecha: string;
  hora_inicio: string;
  hora_fin: string;
  tipo:string;
  observaciones?: string;
  repetir_semanal: boolean;
  duracion_horas?: number;
  es_horario_activo?: boolean;
  personal?: {
    personal_id: number;
    persona?: {
      persona_id: number;
      nombres: string;
      apellidos: string;
      numero_documento: string;
    };
    cargo?: {
      cargo_id: number;
      nombre: string;
    };
  };
  created_at?: string;
  updated_at?: string;
}

export interface CreateHorarioDTO {
  personal_id: number;
  fecha: string;
  hora_inicio: string;
  hora_fin: string;
  tipo?: 'NORMAL' | 'EXTRA' | 'TURNO' | 'FINESEMANA';
  observaciones?: string;
  repetir_semanal?: boolean;
}

export interface UpdateHorarioDTO {
  hora_inicio?: string;
  hora_fin?: string;
  tipo?: 'NORMAL' | 'EXTRA' | 'TURNO' | 'FINESEMANA';
  observaciones?: string;
  repetir_semanal?: boolean;
}

export interface Asistencia {
  asistencia_id: number;
  personal_id: number;
  horario_id?: number;
  fecha: string;
  hora_entrada?: string;
  hora_salida?: string;
  estado_nombre: string;
  observaciones?: string;
  entrada_tarde: boolean;
  salida_temprana: boolean;
  minutos_retraso: number;
  horas_extras_calc?: number;
  horas_trabajadas?: number;
  estadoAsistencia?: {
    estado_asistencia_id: number;
    nombre: string;
    activo: boolean;
  };
  personal?: {
    personal_id: number;
    persona?: {
      persona_id: number;
      nombres: string;
      apellidos: string;
      numero_documento: string;
      foto_cifrada?: string;
    };
    cargo?: {
      cargo_id: number;
      nombre: string;
    };
  };
  horario?: Horario;
  created_at?: string;
  updated_at?: string;
}

export interface RegistrarAsistenciaDTO {
  personal_id: number;
  tipo: 'entrada' | 'salida';
  observaciones?: string;
  estado?: 'PRESENTE' | 'TARDE' | 'JUSTIFICADO';
}

export interface EntradaMasivaDTO {
  personal_ids: number[];
  fecha?: string;
  observaciones?: string;
}

export interface ResumenAsistencia {
  id_personal: number;
  persona_nombres: string;
  persona_apellidos: string;
  cargo_nombre: string;
  dias: {
    [key: string]: {
      horas: string;
      estado: string;
    };
  };
  total_horas: number;
  horas_extras: number;
  tardanzas: number;
}

export interface EstadisticasAsistencia {
  total_presentes: number;
  total_ausentes: number;
  total_tardes: number;
  total_horas_extras: number;
  porcentaje_asistencia: number;
}

export interface ReporteAsistencia {
  titulo: string;
  fecha_inicio?: string;
  fecha_fin?: string;
  estadisticas: Array<{ label: string; value: string | number }>;
  detalle: any[];
}

export interface ReporteParams {
  tipo: 'DIARIO' | 'SEMANAL' | 'MENSUAL' | 'PERSONAL';
  fecha_inicio: string;
  fecha_fin: string;
  personal_id?: number | null;
  formato?: 'json' | 'pdf' | 'excel';
}

export interface ApiResponse<T> {
  success: boolean;
  message?: string;
  data: T;
  errors?: Record<string, string[]>;
  meta?: {
    total: number;
    filtros_aplicados?: any;
  };
}

@Injectable({
  providedIn: 'root'
})
export class CalendarioService {
  private apiUrl = `${environment.apiUrl}`;

  constructor(
    private http: HttpClient,
    private authService: AuthService,
    private notificationService: NotificationService
  ) {}

  private getHeaders(): HttpHeaders {
    const token = this.authService.getToken();
    return new HttpHeaders({
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    });
  }

  private handleError(error: any): Observable<never> {
    console.error('❌ Error en CalendarioService:', error);

    let errorMessage = 'Error desconocido';

    if (error.error instanceof ErrorEvent) {
      errorMessage = `Error del cliente: ${error.error.message}`;
    } else {
      switch (error.status) {
        case 401:
          errorMessage = 'No autorizado. Por favor inicie sesión nuevamente.';
          this.authService.clearAuthData();
          break;
        case 403:
          errorMessage = 'No tiene permisos para realizar esta acción.';
          break;
        case 404:
          errorMessage = 'Recurso no encontrado.';
          break;
        case 422:
          if (error.error?.errors) {
            const errors = Object.values(error.error.errors).flat();
            errorMessage = errors.join(', ');
          } else if (error.error?.message) {
            errorMessage = error.error.message;
          }
          break;
        case 500:
          errorMessage = 'Error interno del servidor. Por favor intente más tarde.';
          break;
        default:
          errorMessage = error.error?.message || `Error ${error.status}: ${error.message}`;
      }
    }

    this.notificationService.showError(errorMessage);
    return throwError(() => new Error(errorMessage));
  }

  // ========== MÉTODOS DE HORARIOS ==========

  getHorarios(filtros?: {
    personal_id?: number;
    fecha_inicio?: string;
    fecha_fin?: string;
    tipo?: string;
  }): Observable<Horario[]> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== null && value !== undefined && value !== '') {
          params = params.append(key, value.toString());
        }
      });
    }

    return this.http.get<ApiResponse<Horario[]>>(`${this.apiUrl}/horarios`, {
      headers: this.getHeaders(),
      params
    }).pipe(
      map(response => response.data),
      catchError(this.handleError)
    );
  }

  crearHorario(datos: CreateHorarioDTO): Observable<Horario> {
    return this.http.post<ApiResponse<Horario>>(`${this.apiUrl}/horarios`, datos, {
      headers: this.getHeaders()
    }).pipe(
      map(response => response.data),
      tap(() => {
        this.notificationService.showSuccess('Horario creado exitosamente');
      }),
      catchError(this.handleError)
    );
  }

  actualizarHorario(id: number, datos: UpdateHorarioDTO): Observable<Horario> {
    return this.http.put<ApiResponse<Horario>>(`${this.apiUrl}/horarios/${id}`, datos, {
      headers: this.getHeaders()
    }).pipe(
      map(response => response.data),
      tap(() => {
        this.notificationService.showSuccess('Horario actualizado exitosamente');
      }),
      catchError(this.handleError)
    );
  }

  eliminarHorario(id: number): Observable<void> {
    return this.http.delete<ApiResponse<void>>(`${this.apiUrl}/horarios/${id}`, {
      headers: this.getHeaders()
    }).pipe(
      map(() => undefined),
      tap(() => {
        this.notificationService.showSuccess('Horario eliminado exitosamente');
      }),
      catchError(this.handleError)
    );
  }

  // ========== MÉTODOS DE ASISTENCIA ==========

  registrarAsistencia(datos: RegistrarAsistenciaDTO): Observable<Asistencia> {
    return this.http.post<ApiResponse<Asistencia>>(`${this.apiUrl}/asistencias/registrar`, datos, {
      headers: this.getHeaders()
    }).pipe(
      map(response => response.data),
      tap(() => {
        const mensaje = datos.tipo === 'entrada'
          ? 'Entrada registrada exitosamente'
          : 'Salida registrada exitosamente';
        this.notificationService.showSuccess(mensaje);
      }),
      catchError(this.handleError)
    );
  }

  registrarEntradaMasiva(datos: EntradaMasivaDTO): Observable<{ registrados: number; errores: any[]; total: number }> {
    return this.http.post<ApiResponse<any>>(`${this.apiUrl}/asistencias/entrada-masiva`, datos, {
      headers: this.getHeaders()
    }).pipe(
      map(response => response.data),
      tap(() => {
        this.notificationService.showSuccess('Entrada masiva registrada');
      }),
      catchError(this.handleError)
    );
  }

  getEstadisticas(): Observable<EstadisticasAsistencia> {
    return this.http.get<ApiResponse<EstadisticasAsistencia>>(`${this.apiUrl}/asistencias/estadisticas`, {
      headers: this.getHeaders()
    }).pipe(
      map(response => response.data),
      catchError(this.handleError)
    );
  }

  exportarExcel(filtros?: {
    fecha_inicio?: string;
    fecha_fin?: string;
    personal_id?: number;
  }): Observable<Blob> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== null && value !== undefined && value !== '') {
          params = params.append(key, value.toString());
        }
      });
    }

    return this.http.get(`${this.apiUrl}/asistencias/exportar-excel`, {
      headers: this.getHeaders(),
      params,
      responseType: 'blob'
    }).pipe(
      tap(() => {
        this.notificationService.showSuccess('Exportando archivo Excel...');
      }),
      catchError(this.handleError)
    );
  }

  exportarPDF(filtros?: {
    fecha_inicio?: string;
    fecha_fin?: string;
    personal_id?: number;
  }): Observable<Blob> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== null && value !== undefined && value !== '') {
          params = params.append(key, value.toString());
        }
      });
    }

    return this.http.get(`${this.apiUrl}/asistencias/exportar-pdf`, {
      headers: this.getHeaders(),
      params,
      responseType: 'blob'
    }).pipe(
      tap(() => {
        this.notificationService.showSuccess('Exportando archivo PDF...');
      }),
      catchError(this.handleError)
    );
  }

getAsistencias(filtros?: any): Observable<Asistencia[]> {
  let params = new HttpParams();
  if (filtros) {
    Object.entries(filtros).forEach(([key, value]) => {
      if (value !== null && value !== undefined && value !== '') {
        params = params.append(key, value.toString());
      }
    });
  }

  return this.http.get<ApiResponse<Asistencia[]>>(`${this.apiUrl}/asistencias`, {
    headers: this.getHeaders(),
    params
  }).pipe(
    map(response => {
      return response.data || [];  // ✅ Esto ya está bien
    }),
    catchError(this.handleError)
  );
}

  // Método existente para resumen
  getResumenAsistencia(filtros?: any): Observable<ResumenAsistencia[]> {
    let params = new HttpParams();

    if (filtros) {
      Object.entries(filtros).forEach(([key, value]) => {
        if (value !== null && value !== undefined && value !== '') {
          params = params.append(key, value.toString());
        }
      });
    }

    return this.http.get<ApiResponse<ResumenAsistencia[]>>(`${this.apiUrl}/asistencias/resumen`, {
      headers: this.getHeaders(),
      params
    }).pipe(
      map(response => response.data),
      catchError(this.handleError)
    );
  }


  // ========== MÉTODOS DE REPORTES ==========

  generarReporte(params: ReporteParams): Observable<ReporteAsistencia> {
    return this.http.post<ApiResponse<ReporteAsistencia>>(`${this.apiUrl}/reportes/asistencia`, params, {
      headers: this.getHeaders()
    }).pipe(
      map(response => response.data),
      tap(() => {
        this.notificationService.showSuccess('Reporte generado exitosamente');
      }),
      catchError(this.handleError)
    );
  }
}
