import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { map, catchError, tap } from 'rxjs/operators';
import { environment } from '../../environments/environment';
import { PersonalService, Personal } from './personal.service';
import { AuthService } from '../core/services/auth.service';

export interface PersonalCalendario {
  personal_id: number;
  persona_id: number;
  persona_nombres: string;
  persona_apellidos: string;
  persona_documento: string;
  cargo_id: number;
  cargo_nombre: string;
  cargo_descripcion?: string;
  fecha_ingreso: string;
  fecha_egreso?: string;
  activo: boolean;
  foto_cifrada?: string;
}

@Injectable({
  providedIn: 'root'
})
export class PersonalCalendarioService {
  private apiUrl = `${environment.apiUrl}/personal`;

  constructor(
    private http: HttpClient,
    private authService: AuthService,
    private personalService: PersonalService  // ✅ Inyectado pero no usado
  ) {}

  private getHeaders() {
    const token = this.authService.getToken();
    return {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    };
  }



  /**
   * Obtener personal activo - Usando el endpoint correcto
   */
  obtenerPersonalActivo(): Observable<PersonalCalendario[]> {

    // ✅ Usar el endpoint específico de activos
    return this.http.get<any>(`${this.apiUrl}/activos`, {
      headers: this.getHeaders()
    }).pipe(
      tap(response => {
      }),
      map(response => {
        if (response && response.success && response.data && response.data.length > 0) {
          return response.data.map((personal: any) => ({
            personal_id: personal.personal_id,
            persona_id: personal.persona_id,
            persona_nombres: personal.persona?.nombres || '',
            persona_apellidos: personal.persona?.apellidos || '',
            persona_documento: personal.persona?.numero_documento || '',
            cargo_id: personal.cargo_id,
            cargo_nombre: personal.cargo?.nombre || 'Sin cargo',
            cargo_descripcion: personal.cargo?.descripcion,
            fecha_ingreso: personal.fecha_ingreso,
            fecha_egreso: personal.fecha_egreso,
            activo: personal.activo,
            foto_cifrada: personal.persona?.foto_cifrada
          }));
        }
        return [];
      }),
      catchError((error) => {
        console.error('❌ Error obteniendo personal activo:', error);
        return of([]);
      })
    );
  }

  /**
   * Método para buscar personal
   */
  buscarPersonal(termino: string): Observable<PersonalCalendario[]> {
    return this.personalService.listarPersonal({ search: termino, activo: true }).pipe(
      map(response => {
        if (response && response.success && response.data) {
          return response.data.map((personal: Personal) => ({
            personal_id: personal.personal_id,
            persona_id: personal.persona_id,
            persona_nombres: personal.persona?.nombres || '',
            persona_apellidos: personal.persona?.apellidos || '',
            persona_documento: personal.persona?.numero_documento || '',
            cargo_id: personal.cargo_id,
            cargo_nombre: personal.cargo?.nombre || 'Sin cargo',
            cargo_descripcion: personal.cargo?.descripcion,
            fecha_ingreso: personal.fecha_ingreso,
            fecha_egreso: personal.fecha_egreso,
            activo: personal.activo,
            foto_cifrada: personal.persona?.foto_cifrada
          }));
        }
        return [];
      })
    );
  }
}
