import { ReportBuilder } from './report-builder.interface';

export class AsistenciaReportBuilder implements ReportBuilder {
  private report: any = {
    titulo: '',
    fecha_generacion: new Date().toISOString(),
    estadisticas: [],
    detalle: [],
    personal: null
  };

  setTitle(title: string): this {
    this.report.titulo = title;
    return this;
  }

  setPeriod(start: string, end: string): this {
    this.report.periodo = { inicio: start, fin: end };
    return this;
  }

  addStatistic(label: string, value: string | number): this {
    this.report.estadisticas.push({ label, value });
    return this;
  }

  addDetail(item: any): this {
    this.report.detalle.push(item);
    return this;
  }

  setPersonalData(personal: any): this {
    this.report.personal = personal;
    return this;
  }

  build(): any {
    return { ...this.report };
  }

  reset(): void {
    this.report = {
      titulo: '',
      fecha_generacion: new Date().toISOString(),
      estadisticas: [],
      detalle: [],
      personal: null
    };
  }
}
