import { CalendarState } from './calendar-state.interface';

export class WeekViewState implements CalendarState {
  getTitle(): string {
    return 'Vista Semana';
  }

  getDateRange(currentDate: Date): string {
    const start = this.getStartOfWeek(currentDate);
    const end = this.getEndOfWeek(currentDate);
    return `${start.toLocaleDateString('es', { day: 'numeric', month: 'short' })} - ${end.toLocaleDateString('es', { day: 'numeric', month: 'short', year: 'numeric' })}`;
  }

  navigate(currentDate: Date, direction: 'prev' | 'next'): Date {
    const newDate = new Date(currentDate);
    newDate.setDate(currentDate.getDate() + (direction === 'next' ? 7 : -7));
    return newDate;
  }

  getViewData(date: Date, data: any): any {
    const days = this.getDaysOfWeek(date);
    return {
      date,
      days,
      hours: Array.from({ length: 12 }, (_, i) => i + 6)
    };
  }

  private getStartOfWeek(date: Date): Date {
    const start = new Date(date);
    const day = start.getDay();
    start.setDate(start.getDate() - (day === 0 ? 6 : day - 1));
    return start;
  }

  private getEndOfWeek(date: Date): Date {
    const end = this.getStartOfWeek(date);
    end.setDate(end.getDate() + 6);
    return end;
  }

  private getDaysOfWeek(date: Date): any[] {
    const start = this.getStartOfWeek(date);
    const days = [];

    for (let i = 0; i < 7; i++) {
      const current = new Date(start);
      current.setDate(start.getDate() + i);
      days.push({
        name: current.toLocaleDateString('es', { weekday: 'long' }),
        shortName: current.toLocaleDateString('es', { weekday: 'short' }),
        date: current.toISOString().split('T')[0],
        dayNumber: current.getDate()
      });
    }

    return days;
  }
}
