import { Injectable, inject } from '@angular/core';
import { BehaviorSubject, Observable, combineLatest, map, tap } from 'rxjs';
import { CalendarRepository, CALENDAR_REPOSITORY } from '../repositories/calendar-repository.interface';
import { FilterContext } from '../strategies/filter-context';
import { PersonalFilterStrategy } from '../strategies/personal-filter.strategy';
import { EstadoFilterStrategy } from '../strategies/estado-filter.strategy';
import { AsistenciaReportBuilder } from '../builders/asistencia-report.builder';
import { ReportDirector } from '../builders/report-director';
import { DayViewState, WeekViewState, MonthViewState } from '../states';
import { Horario, Asistencia, ResumenAsistencia, EstadisticasAsistencia } from '../../../services/calendario.service';
import { PersonalCalendario } from '../../../services/personal-calendario.service';
import { NotificationService } from '../../../core/services/notification/notification.service';
import { CalendarRepositoryImpl } from '../repositories/calendar-repository.impl';

export interface ViewData {
  view: 'day' | 'week' | 'month';
  date: Date;
  viewData: any;
  title: string;
  dateRange: string;
}

@Injectable()
export class CalendarFacade {
  private repository = inject<CalendarRepository>(CALENDAR_REPOSITORY as any);
  private filterContext = new FilterContext();
  private currentDateSubject = new BehaviorSubject<Date>(new Date());
  private viewSubject = new BehaviorSubject<'day' | 'week' | 'month'>('week');
  private notificationService = inject(NotificationService);

  private states = {
    day: new DayViewState(),
    week: new WeekViewState(),
    month: new MonthViewState()
  };

  // ✅ AGREGAR asistencias$
  public personal$: Observable<PersonalCalendario[]> = this.repository.getPersonal();
  public horarios$: Observable<Horario[]> = this.repository.getHorarios();
  public asistencias$: Observable<Asistencia[]> = this.repository.getAsistencias();
  public resumen$: Observable<ResumenAsistencia[]> = this.repository.getResumenAsistencia();
  public estadisticas$: Observable<EstadisticasAsistencia> = this.repository.getEstadisticas();

  public viewState$: Observable<ViewData> = combineLatest([
    this.currentDateSubject,
    this.viewSubject,
    this.resumen$
  ]).pipe(
    map(([date, view, resumen]) => ({
      view,
      date,
      viewData: this.states[view].getViewData(date, { events: resumen }),
      title: this.states[view].getTitle(),
      dateRange: this.states[view].getDateRange(date)
    }))
  );

  private filtersSubject = new BehaviorSubject<Record<string, any>>({});
  public filteredPersonal$: Observable<PersonalCalendario[]> = combineLatest([
    this.personal$,
    this.filtersSubject
  ]).pipe(
    map(([personal, filters]) => this.filterContext.applyFilters(personal, filters))
  );

  constructor() {
    this.filterContext.registerStrategy(new PersonalFilterStrategy());
    this.filterContext.registerStrategy(new EstadoFilterStrategy());
  }

  // Navegación
  navigate(direction: 'prev' | 'next'): void {
    const currentDate = this.currentDateSubject.value;
    const currentView = this.viewSubject.value;
    const newDate = this.states[currentView].navigate(currentDate, direction);
    this.currentDateSubject.next(newDate);
    this.refreshData();
  }

  goToToday(): void {
    this.currentDateSubject.next(new Date());
    this.refreshData();
  }

  changeView(view: 'day' | 'week' | 'month'): void {
    this.viewSubject.next(view);
    this.refreshData();
  }

  // Filtros
  setFilter(key: string, value: any): void {
    const currentFilters = this.filtersSubject.value;
    this.filtersSubject.next({ ...currentFilters, [key]: value });
  }

  clearFilters(): void {
    this.filtersSubject.next({});
  }


  crearHorario(data: any): Observable<Horario> {
    return this.repository.crearHorario(data).pipe(
      tap(() => this.refreshData())
    );
  }

  actualizarHorario(id: number, data: any): Observable<Horario> {
    return this.repository.actualizarHorario(id, data).pipe(
      tap(() => this.refreshData())
    );
  }

  eliminarHorario(id: number): Observable<void> {
    return this.repository.eliminarHorario(id).pipe(
      tap(() => this.refreshData())
    );
  }



  // Reportes
  generarReporte(tipo: 'diario' | 'semanal' | 'mensual' | 'personal', params: any): any {
    const builder = new AsistenciaReportBuilder();
    const director = new ReportDirector(builder);

    switch (tipo) {
      case 'diario':
        return director.buildDiarioReport(
          params.fecha,
          params.estadisticas || {},
          params.detalle || []
        );
      case 'semanal':
        return director.buildSemanalReport(
          params.inicio,
          params.fin,
          params.estadisticas || {},
          params.detalle || []
        );
      case 'mensual':
        return director.buildMensualReport(
          params.mes || params.fecha,
          params.estadisticas || {},
          params.detalle || []
        );
      case 'personal':
        return director.buildPersonalReport(
          params.personal,
          params.periodo,
          params.estadisticas || {},
          params.detalle || []
        );
      default:
        return builder.build();
    }
  }


registrarSalida(personalId: number, fecha?: string): Observable<Asistencia> {
  const payload: any = {
    personal_id: personalId,
    tipo: 'salida'
  };

  if (fecha) {
    payload.fecha = fecha;  // ✅ Enviar fecha al backend
  }

  return this.repository.registrarAsistencia(payload).pipe(
    tap((asistencia) => {
      this.refreshData();
    })
  );
}

registrarEntrada(personalId: number, estadoId?: number, observaciones?: string, fecha?: string): Observable<Asistencia> {
  const payload: any = {
    personal_id: personalId,
    tipo: 'entrada',
    estado_id: estadoId,  // ✅ Enviar el ID del estado
    observaciones
  };

  if (fecha) {
    payload.fecha = fecha;
  }

  return this.repository.registrarAsistencia(payload).pipe(
    tap((asistencia) => {
      this.refreshData();
    })
  );
}
refreshData(filtros?: { fecha_inicio?: string; fecha_fin?: string }): void {
    (this.repository as CalendarRepositoryImpl).recargarTodosLosDatos(filtros);
}

// Agregar método para actualizar resumen con fechas específicas
actualizarResumenConFechas(fechaInicio: string, fechaFin: string): void {
    const filtros = { fecha_inicio: fechaInicio, fecha_fin: fechaFin };
    console.log('📊 Actualizando resumen con fechas:', filtros);

    this.repository.getResumenAsistencia(filtros).subscribe({
        next: (resumen) => {
            // Actualizar el BehaviorSubject interno del repositorio
            (this.repository as CalendarRepositoryImpl)['resumenSubject'].next(resumen);
            console.log('✅ Resumen actualizado:', resumen.length);
        },
        error: (err) => console.error('Error actualizando resumen:', err)
    });
}

}

