import { FilterStrategy } from './filter-strategy.interface';
import { PersonalCalendario } from '../../../services/personal-calendario.service';

export class PersonalFilterStrategy implements FilterStrategy {
  filter(data: PersonalCalendario[], criteria: { personalId: number | null }): PersonalCalendario[] {
    if (!criteria.personalId) return data;
    return data.filter(item => item.personal_id === criteria.personalId);
  }

  getFilterKey(): string {
    return 'personal';
  }
}
