import { FilterStrategy } from './filter-strategy.interface';
import { PersonalCalendario } from '../../../services/personal-calendario.service';

export class FilterContext {
  private strategies: Map<string, FilterStrategy> = new Map();

  registerStrategy(strategy: FilterStrategy): void {
    this.strategies.set(strategy.getFilterKey(), strategy);
  }

  applyFilters(data: PersonalCalendario[], filters: Record<string, any>): PersonalCalendario[] {
    let result = [...data];

    for (const [key, value] of Object.entries(filters)) {
      const strategy = this.strategies.get(key);
      if (strategy && value !== null && value !== undefined && value !== '') {
        result = strategy.filter(result, { [key]: value });
      }
    }

    return result;
  }
}
