import { FilterStrategy } from './filter-strategy.interface';
import { PersonalCalendario } from '../../../services/personal-calendario.service';

export class EstadoFilterStrategy implements FilterStrategy {
  filter(data: PersonalCalendario[], criteria: { estado: string | null }): PersonalCalendario[] {
    if (!criteria.estado) return data;
    // El filtro por estado requiere datos de asistencia, se implementa en el servicio
    return data;
  }

  getFilterKey(): string {
    return 'estado';
  }
}
