import { CalendarState } from './calendar-state.interface';

export class DayViewState implements CalendarState {
  getTitle(): string {
    return 'Vista Día';
  }

  getDateRange(currentDate: Date): string {
    return currentDate.toLocaleDateString('es', {
      weekday: 'long',
      day: 'numeric',
      month: 'long'
    });
  }

  navigate(currentDate: Date, direction: 'prev' | 'next'): Date {
    const newDate = new Date(currentDate);
    newDate.setDate(currentDate.getDate() + (direction === 'next' ? 1 : -1));
    return newDate;
  }

  getViewData(date: Date, data: any): any {
    return {
      date,
      hours: Array.from({ length: 24 }, (_, i) => i),
      events: data.events?.filter((e: any) => e.date === date.toISOString().split('T')[0]) || []
    };
  }
}
