import { ReportBuilder } from './report-builder.interface';

// Interfaz para estadísticas
export interface EstadisticasReporte {
  totalPersonal: number;
  presentes: number;
  ausentes: number;
  tardes: number;
  horasTotales: number;
  horasExtras: number;
  diasTrabajados: number;
  tardanzas: number;
}

export class ReportDirector {
  constructor(private builder: ReportBuilder) {}

  buildDiarioReport(
    fecha: string,
    estadisticas: Partial<EstadisticasReporte>,
    detalle: any[]
  ): any {
    return this.builder
      .setTitle(`Reporte Diario - ${fecha}`)
      .setPeriod(fecha, fecha)
      .addStatistic('Total Personal', estadisticas.totalPersonal || 0)
      .addStatistic('Presentes', estadisticas.presentes || 0)
      .addStatistic('Ausentes', estadisticas.ausentes || 0)
      .addStatistic('Tardanzas', estadisticas.tardes || 0)
      .build();
  }

  buildSemanalReport(
    inicio: string,
    fin: string,
    estadisticas: Partial<EstadisticasReporte>,
    detalle: any[]
  ): any {
    return this.builder
      .setTitle(`Reporte Semanal - ${inicio} al ${fin}`)
      .setPeriod(inicio, fin)
      .addStatistic('Total Personal', estadisticas.totalPersonal || 0)
      .addStatistic('Horas Totales', estadisticas.horasTotales || 0)
      .addStatistic('Horas Extras', estadisticas.horasExtras || 0)
      .build();
  }

  buildPersonalReport(
    personal: any,
    periodo: any,
    estadisticas: Partial<EstadisticasReporte>,
    detalle: any[]
  ): any {
    return this.builder
      .setTitle(`Reporte de Asistencia - ${personal.nombre_completo}`)
      .setPeriod(periodo.inicio, periodo.fin)
      .setPersonalData(personal)
      .addStatistic('Días Trabajados', estadisticas.diasTrabajados || 0)
      .addStatistic('Horas Totales', estadisticas.horasTotales || 0)
      .addStatistic('Horas Extras', estadisticas.horasExtras || 0)
      .addStatistic('Tardanzas', estadisticas.tardanzas || 0)
      .build();
  }

  buildMensualReport(
    mes: string,
    estadisticas: Partial<EstadisticasReporte>,
    detalle: any[]
  ): any {
    return this.builder
      .setTitle(`Reporte Mensual - ${mes}`)
      .setPeriod('', '')
      .addStatistic('Total Personal', estadisticas.totalPersonal || 0)
      .addStatistic('Horas Totales', estadisticas.horasTotales || 0)
      .addStatistic('Horas Extras', estadisticas.horasExtras || 0)
      .addStatistic('Tardanzas', estadisticas.tardanzas || 0)
      .build();
  }
}
