import { Injectable } from '@angular/core';
import { CalendarRepository } from './calendar-repository.interface';
import { CalendarioService, Horario, Asistencia, ResumenAsistencia, EstadisticasAsistencia } from '../../../services/calendario.service';
import { PersonalCalendarioService, PersonalCalendario } from '../../../services/personal-calendario.service';
import { BehaviorSubject, Observable, tap} from 'rxjs';


@Injectable()
export class CalendarRepositoryImpl implements CalendarRepository {
    private personalSubject = new BehaviorSubject<PersonalCalendario[]>([]);
  private horariosSubject = new BehaviorSubject<Horario[]>([]);
  private asistenciasSubject = new BehaviorSubject<Asistencia[]>([]);
  private resumenSubject = new BehaviorSubject<ResumenAsistencia[]>([]);
  private estadisticasSubject = new BehaviorSubject<EstadisticasAsistencia>({
    total_presentes: 0,
    total_ausentes: 0,
    total_tardes: 0,
    total_horas_extras: 0,
    porcentaje_asistencia: 0
  });

  constructor(
    private calendarioService: CalendarioService,
    private personalCalendarioService: PersonalCalendarioService
  ) { this.cargarDatosIniciales();   }

    // Cargar datos iniciales
    private cargarDatosIniciales(): void {
        this.recargarTodosLosDatos();
    }

recargarTodosLosDatos(filtros?: { fecha_inicio?: string; fecha_fin?: string }): void {

    this.personalCalendarioService.obtenerPersonalActivo().subscribe(data => {
        this.personalSubject.next(data);
    });

    this.calendarioService.getHorarios().subscribe(data => {
        this.horariosSubject.next(data);
    });

    // ✅ Cargar asistencias CON filtros de fecha
    this.calendarioService.getAsistencias(filtros).subscribe(data => {
        this.asistenciasSubject.next(data);
    });

    // ✅ Cargar resumen CON filtros de fecha
    this.calendarioService.getResumenAsistencia(filtros).subscribe(data => {
        this.resumenSubject.next(data);
    });

    this.calendarioService.getEstadisticas().subscribe(data => {
        this.estadisticasSubject.next(data);
    });
}

      registrarAsistencia(data: any): Observable<Asistencia> {
        return this.calendarioService.registrarAsistencia(data).pipe(
            tap(asistencia => {
                // ✅ Recargar todos los datos después de registrar
                this.recargarTodosLosDatos();
            })
        );
    }

    crearHorario(data: any): Observable<Horario> {
        return this.calendarioService.crearHorario(data).pipe(
            tap(horario => {
                this.recargarTodosLosDatos();
            })
        );
    }

  // ✅ Los métodos get devuelven los Subjects como Observables
  getHorarios(filters?: any): Observable<Horario[]> {
    if (filters) {
      return this.calendarioService.getHorarios(filters);
    }
    return this.horariosSubject.asObservable();
  }

  getAsistencias(filters?: any): Observable<Asistencia[]> {
    if (filters) {
      return this.calendarioService.getAsistencias(filters);
    }
    return this.asistenciasSubject.asObservable();
  }

  getPersonal(): Observable<PersonalCalendario[]> {
    return this.personalSubject.asObservable();
  }

  getResumenAsistencia(filters?: any): Observable<ResumenAsistencia[]> {
    if (filters) {
      return this.calendarioService.getResumenAsistencia(filters);
    }
    return this.resumenSubject.asObservable();
  }

  getEstadisticas(): Observable<EstadisticasAsistencia> {
    return this.estadisticasSubject.asObservable();
  }

  actualizarHorario(id: number, data: any): Observable<Horario> {
    return this.calendarioService.actualizarHorario(id, data).pipe(
      tap(horario => {
        this.calendarioService.getHorarios().subscribe(horarios => {
          this.horariosSubject.next(horarios);
        });
      })
    );
  }

  eliminarHorario(id: number): Observable<void> {
    return this.calendarioService.eliminarHorario(id).pipe(
      tap(() => {
        this.calendarioService.getHorarios().subscribe(horarios => {
          this.horariosSubject.next(horarios);
        });
      })
    );
  }
}

